	Mat4 expected = hierarchy.A->local_to_parent();
	Mat4 mat = hierarchy.A->local_to_world();

	if (Test::differs(mat, expected)) {
		info("Transform A's local_to_world:");
		Test::print_matrix(mat);
		info("Transform A's local_to_parent:");
