	HalfedgeRef h2 = emplace_halfedge();
	HalfedgeRef t2 = emplace_halfedge();

	h2->set_tnvef(t, h_next, vm, e2, h->face);
	t2->set_tnvef(h, t_next, vm, e, t->face);

	h->twin = t2;
	h->next = h2;

	t->twin = h2;
	t->next = t2;
	t->edge = e2;

	e->halfedge = h;
	e2->halfedge = h2;
	vm->halfedge = h2;

	interpolate_data({HalfedgeCRef(h), HalfedgeCRef(h_next)}, h2);
	interpolate_data({HalfedgeCRef(t), HalfedgeCRef(t_next)}, t2);

	return vm;
}


