Vec3 fallback_tangent(Vec3 n) {
	Vec3 axis = (std::abs(n.z) < 0.9f) ? Vec3(0.0f, 0.0f, 1.0f) : Vec3(0.0f, 1.0f, 0.0f);
	Vec3 t = cross(axis, n);
	if (t.norm_squared() == 0.0f) {
		t = cross(Vec3(1.0f, 0.0f, 0.0f), n);
	}
	return t.unit();
}

