/*
 * catmark_subdivide_helper: add vertex in every edge and non-boundary face, set positions from parameters
 *
 * Works on all valid meshes.
 */
void Halfedge_Mesh::catmark_subdivide_helper(
	std::unordered_map< VertexCRef, Vec3 > const &vertex_positions, //positions for vertices after subdivision
	std::unordered_map< EdgeCRef, Vec3 > const &edge_vertex_positions, //positions for new vertices added in each edge
	std::unordered_map< FaceCRef, Vec3 > const &face_vertex_positions //positions for new vertices added in each face
	) {
	std::unordered_map<VertexCRef, Index> vertex_index;
	std::unordered_map<EdgeCRef, Index> edge_index;

	std::unordered_map<EdgeCRef, Index> edge_index;
	std::unordered_map<FaceCRef, Index> face_index;

	std::vector<Vec3> new_vertices;
	new_vertices.reserve(vertex_positions.size() + edge_vertex_positions.size() + face_vertex_positions.size());

	for (VertexCRef v = vertices.begin(); v != vertices.end(); ++v) {
		vertex_index.emplace(v, static_cast<Index>(new_vertices.size()));
		new_vertices.emplace_back(vertex_positions.at(v));
	}
	for (EdgeCRef e = edges.begin(); e != edges.end(); ++e) {
		edge_index.emplace(e, static_cast<Index>(new_vertices.size()));
		new_vertices.emplace_back(edge_vertex_positions.at(e));
	}
	for (FaceCRef f = faces.begin(); f != faces.end(); ++f) {
		if (f->boundary) continue;
		face_index.emplace(f, static_cast<Index>(new_vertices.size()));
		new_vertices.emplace_back(face_vertex_positions.at(f));
	}

	std::vector<std::vector<Index>> new_faces;
	for (FaceCRef f = faces.begin(); f != faces.end(); ++f) {
		if (f->boundary) continue;

		std::vector<HalfedgeCRef> ring;
		HalfedgeCRef h = f->halfedge;
		do {
			ring.emplace_back(h);
			h = h->next;
		} while (h != f->halfedge);

		for (HalfedgeCRef he : ring) {
			HalfedgeCRef prev = prev_in_face(he);
			new_faces.emplace_back(std::vector<Index>{
				vertex_index.at(he->vertex),
				edge_index.at(he->edge),
				face_index.at(f),
				edge_index.at(prev->edge)
			});
		}
	}

	Halfedge_Mesh refined = Halfedge_Mesh::from_indexed_faces(new_vertices, new_faces);
	*this = std::move(refined);
}

/*
 * flip_orientation: flip direction of all halfedges
 *
 * works on all valid meshes.
 */
void Halfedge_Mesh::flip_orientation() {
	std::unordered_map<HalfedgeRef, HalfedgeRef> prev;
	std::unordered_map<HalfedgeRef, VertexRef> destination;

	for (FaceCRef f = faces.begin(); f != faces.end(); ++f) {
		HalfedgeRef start = f->halfedge;
		HalfedgeRef h = start;
		do {
			prev[h->next] = h;
			destination[h] = h->twin->vertex;
			h = h->next;
		} while (h != start);
	}

	for (HalfedgeRef h = halfedges.begin(); h != halfedges.end(); ++h) {
		h->next = prev.at(h);
		h->vertex = destination.at(h);
	}

	for (VertexRef v = vertices.begin(); v != vertices.end(); ++v) {
		v->halfedge = halfedges.end();
	}
	for (HalfedgeRef h = halfedges.begin(); h != halfedges.end(); ++h) {
		h->vertex->halfedge = h;
	}
}

/*
 * set_corner_normals: compute face-corner normals based on `sharp` flag and smoothing threshold
 *
 * works on all valid meshes.
 */
void Halfedge_Mesh::set_corner_normals(float threshold) {
	std::unordered_map<EdgeCRef, bool> sharp_edges;
	for (EdgeCRef e = edges.begin(); e != edges.end(); ++e) {
		bool sharp = false;
		if (threshold <= 0.0f) {
			sharp = true;
		} else if (e->on_boundary()) {
			sharp = true;
		} else if (threshold >= 180.0f) {
			sharp = false;
		} else {
			sharp = e->sharp;
			if (!sharp) {
				float cosine = std::clamp(dot(e->halfedge->face->normal(), e->halfedge->twin->face->normal()), -1.0f, 1.0f);
				float angle = std::acos(cosine) * 180.0f / PI_F;
				sharp = angle > threshold;
			}
		}
		sharp_edges.emplace(e, sharp);
	}

	for (HalfedgeRef h = halfedges.begin(); h != halfedges.end(); ++h) {
		if (h->face->boundary) {
			h->corner_normal = Vec3(0.0f);
			continue;
		}

		Vec3 sum = Vec3(0.0f);
		std::unordered_set<FaceCRef> visited;

		auto add_face = [&](HalfedgeCRef he) {
			if (!he->face->boundary && visited.emplace(he->face).second) {
				sum += he->face->normal();
				return true;
			}
			return false;
		};

		add_face(h);

		HalfedgeCRef walk = h;
		while (!sharp_edges.at(walk->edge) && !walk->twin->face->boundary) {
			walk = walk->twin->next;
			if (walk == h || !add_face(walk)) break;
		}

		walk = h;
		while (true) {
			HalfedgeCRef incoming = prev_in_face(walk);
			if (sharp_edges.at(incoming->edge) || incoming->twin->face->boundary) break;
			walk = incoming->twin;
			if (walk == h || !add_face(walk)) break;
		}

		h->corner_normal = (sum == Vec3(0.0f)) ? Vec3(0.0f) : sum.unit();
	}
}

/*
 * set_corner_uvs_per_face: set uv coordinates to map texture per-face
 */
void Halfedge_Mesh::set_corner_uvs_per_face() {
	for (FaceRef f = faces.begin(); f != faces.end(); ++f) {
		if (f->boundary) {
			HalfedgeRef h = f->halfedge;
			do {
				h->corner_uv = Vec2(0.0f);
				h = h->next;
			} while (h != f->halfedge);
			continue;
		}

		Vec3 normal = f->normal();
		HalfedgeRef h = f->halfedge;
		Vec3 tangent = h->next->vertex->position - h->vertex->position;
		tangent = tangent - dot(tangent, normal) * normal;
		if (tangent.norm_squared() == 0.0f) {
			tangent = fallback_tangent(normal);
		} else {
			tangent = tangent.unit();
		}
		Vec3 bitangent = cross(normal, tangent).unit();
		Vec3 origin = f->center();

		do {
			Vec3 delta = h->vertex->position - origin;
			h->corner_uv = Vec2(dot(delta, tangent), dot(delta, bitangent));
			h = h->next;
		} while (h != f->halfedge);
	}
}

/*
 * set_corner_uvs_project: set uv coordinates to map texture by projection to a plane
 */
void Halfedge_Mesh::set_corner_uvs_project(Vec3 origin, Vec3 u_axis, Vec3 v_axis) {

	u_axis /= u_axis.norm_squared();
	v_axis /= v_axis.norm_squared();

	for (auto &halfedge : halfedges) {
		if (halfedge.face->boundary) {
			halfedge.corner_uv = Vec2(0.0f, 0.0f);
		} else {
			halfedge.corner_uv = Vec2(
				dot(halfedge.vertex->position - origin, u_axis),
				dot(halfedge.vertex->position - origin, v_axis)
			);
		}
	}
}

