static void dump_mesh(char const* label, Halfedge_Mesh const& mesh) {
	std::cout << label << ": V=" << mesh.vertices.size()
	          << " E=" << mesh.edges.size()
	          << " F=" << mesh.faces.size()
	          << " B=" << mesh.n_boundaries() << "\n";

	size_t vi = 0;
	for (auto v = mesh.vertices.begin(); v != mesh.vertices.end(); ++v, ++vi) {
		std::cout << "  v" << vi << " id=" << v->id << " pos=("
		          << v->position.x << "," << v->position.y << "," << v->position.z << ")\n";
	}

	size_t fi = 0;
	for (auto f = mesh.faces.begin(); f != mesh.faces.end(); ++f, ++fi) {
		std::cout << "  f" << fi << (f->boundary ? " boundary" : "") << ":";
		auto h = f->halfedge;
		do {
			std::cout << " " << h->vertex->position;
			h = h->next;
		} while (h != f->halfedge);
		std::cout << "\n";
	}
}

