	if (auto msg = square.validate()) {
		std::cout << "validate error: " << msg->second << "\n";
	}
	dump_mesh("square after linear", square);

	Halfedge_Mesh cc_square = Halfedge_Mesh::from_indexed_faces({
		Vec3{-1.0f, 1.0f, 0.0f}, Vec3{1.0f, 1.0f, 0.0f},
		Vec3{-1.0f, -1.0f, 0.0f}, Vec3{1.0f, -1.0f, 0.0f}
	}, {
		{2, 3, 1, 0}
	});

	cc_square.catmark_subdivide();
	if (auto msg = cc_square.validate()) {
		std::cout << "cc validate error: " << msg->second << "\n";
	}
	dump_mesh("square after catmark", cc_square);

	return 0;
}

