	float c2 = std::cos(Radians(angles[1] * 0.5f));
	float c3 = std::cos(Radians(angles[0] * 0.5f));
	float s1 = std::sin(Radians(angles[2] * 0.5f));
	float s2 = std::sin(Radians(angles[1] * 0.5f));
	float s3 = std::sin(Radians(angles[0] * 0.5f));
